import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.LX5S0jbT.js";const r=JSON.parse('{"title":"在 tmux 中运行 Pi","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tmux.md","filePath":"zh/tmux.md"}'),n={name:"zh/tmux.md"};function o(d,e,l,p,c,u){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="在-tmux-中运行-pi" tabindex="-1">在 tmux 中运行 Pi <a class="header-anchor" href="#在-tmux-中运行-pi" aria-label="Permalink to &quot;在 tmux 中运行 Pi&quot;">​</a></h1><p>Pi 可以在 tmux 内运行，但 tmux 可能把 <code>Shift+Enter</code>、<code>Ctrl+Enter</code> 和普通 <code>Enter</code> 上报为同一个键。启用扩展按键（extended keys），让 Pi 能够区分它们。</p><h2 id="检查-tmux-版本" tabindex="-1">检查 tmux 版本 <a class="header-anchor" href="#检查-tmux-版本" aria-label="Permalink to &quot;检查 tmux 版本&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tmux</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -V</span></span></code></pre></div><p>tmux 3.5 及更新版本使用下方推荐的 CSI-u 配置。tmux 3.2 到 3.4 使用旧版本配置。</p><h2 id="在-tmux-3-5-及更新版本中启用扩展按键" tabindex="-1">在 tmux 3.5 及更新版本中启用扩展按键 <a class="header-anchor" href="#在-tmux-3-5-及更新版本中启用扩展按键" aria-label="Permalink to &quot;在 tmux 3.5 及更新版本中启用扩展按键&quot;">​</a></h2><p>在 <code>~/.tmux.conf</code> 中添加以下行：</p><div class="language-tmux vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tmux</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set -g extended-keys on</span></span>
<span class="line"><span>set -g extended-keys-format csi-u</span></span></code></pre></div><p>当终端不直接提供 Kitty 键盘协议时，Pi 会请求扩展按键上报。CSI-u 是通过 tmux 转发修饰键最可靠的格式。</p><h2 id="重启-tmux" tabindex="-1">重启 tmux <a class="header-anchor" href="#重启-tmux" aria-label="Permalink to &quot;重启 tmux&quot;">​</a></h2><p>配置作用于 tmux 服务器。为确保配置生效，关闭你的 tmux 会话并启动新的服务器。</p><p>如果选择从命令行停止服务器，请先保存工作。以下命令会终止该服务器管理的所有会话：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tmux</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kill-server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tmux</span></span></code></pre></div><h2 id="验证修饰键" tabindex="-1">验证修饰键 <a class="header-anchor" href="#验证修饰键" aria-label="Permalink to &quot;验证修饰键&quot;">​</a></h2><p>在新的 tmux 会话中启动 Pi，并检查：</p><ol><li><code>Shift+Enter</code> 在编辑器中插入新行。</li><li><code>Enter</code> 提交提示词。</li><li><code>Alt+Enter</code> 在 macOS 和 Linux 上排队后续消息。Windows 和 WSL 默认使用 <code>Ctrl+Q</code>。</li></ol><p>如果这些键仍然表现为普通 <code>Enter</code>，检查 tmux 外层的终端能否上报修饰键。见<a href="./terminal-setup.html">配置终端</a>。</p><h2 id="使用-tmux-3-2-到-3-4" tabindex="-1">使用 tmux 3.2 到 3.4 <a class="header-anchor" href="#使用-tmux-3-2-到-3-4" aria-label="Permalink to &quot;使用 tmux 3.2 到 3.4&quot;">​</a></h2><p>这些版本支持扩展按键，但不支持 <code>extended-keys-format csi-u</code>。只需添加：</p><div class="language-tmux vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tmux</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set -g extended-keys on</span></span></code></pre></div><p>Pi 支持这些版本使用的 xterm <code>modifyOtherKeys</code> 格式。重启 tmux 并重复验证步骤。</p><p>对更旧的版本，请升级 tmux 或在 tmux 外使用 Pi，不要依赖修饰的 Enter 快捷键。</p>`,22)])])}const m=t(n,[["render",o]]);export{r as __pageData,m as default};
